={{ (() => {
    const telSucRaw = String($fromAI('telefono_sucursal', 'Número de WhatsApp interno de la sucursal elegida') || '').replace(/\D/g, '');
    const rawRes = String($fromAI('resumen', 'Resumen completo de la derivación incluyendo vehículo, servicio y teléfono del cliente') || '');
    const telCliAI = String($fromAI('telefono_cliente', 'Teléfono de WhatsApp del cliente (ej. 549...)', 'string') || '').replace(/\D/g, '');
    let ctx = {};
    try { ctx = $('Evaluar Estado y Contexto').first().json || {}; } catch (e) {}
    let wh = {};
    try { wh = $('Code in JavaScript').first().json || {}; } catch (e) {}

    const telCli = String(
      ctx.telefonoCliente ||
      wh.telefonoCliente ||
      (ctx.remoteJid ? String(ctx.remoteJid).replace('@s.whatsapp.net', '') : '') ||
      (wh.remoteJid ? String(wh.remoteJid).replace('@s.whatsapp.net', '') : '') ||
      ($json && $json.telefonoCliente ? $json.telefonoCliente : '') ||
      telCliAI ||
      ''
    ).replace(/\D/g, '');

    const nomCli = String(
      ctx.pushName ||
      wh.pushName ||
      ($json && $json.pushName ? $json.pushName : '') ||
      'Cliente'
    ).trim();

    const namesByPhone = {
      '5492944579792': 'Check Oil Suc. Centro (Bariloche)',
      '5492944638500': 'Check Oil Suc. Estadio (Bariloche)',
      '5492944907667': 'Check Oil Suc. Ñireco (Bariloche)',
      '5492944615570': 'Check Oil Suc. Km13 (Bariloche)',
      '5492944631155': 'Check Oil Suc. Bolsón (El Bolsón)',
      '5491161217529': 'Check Oil Suc. Dominico (Avellaneda)'
    };

    const telSuc = telSucRaw || '5492944579792';
    const esCentroSinConfirmar =
      telSuc === '5492944579792' &&
      ctx.intermediarioActivoHoy !== false &&
      ctx.estadoCotizacionAnterior !== 'presupuesto_enviado';

    if (esCentroSinConfirmar) {
      const sinTelefono = rawRes
        .replace(/Tel[eé]fono[^\n]*/gi, 'Cliente en línea: Esperando presupuesto a través del Bot')
        .replace(/https?:\/\/wa\.me\/[0-9]+/gi, '')
        .replace(/=== NUEVA DERIVACI[OÓ]N ===/gi, '🧾 SOLICITUD DE PRESUPUESTO #' + (ctx.ticketIdSugerido || 'COT'));
      return {
        number: telSuc,
        text: sinTelefono + '\n\n👉 Respondé citando este mensaje con el PDF del presupuesto (o pregunta para el cliente).'
      };
    }

    const sucNombre = namesByPhone[telSuc] || 'Sucursal Check-Oil';
    let textoFinal = rawRes
      .replace(/🧾\s*SOLICITUD DE PRESUPUESTO[^\n]*/gi, '=== NUEVA DERIVACIÓN ===\nSucursal elegida: ' + sucNombre)
      .replace(/👉\s*Respond[eé] citando[^\n]*/gi, '')
      .replace(/Tel[eé]fono(?: de contacto)?:\s*(?:Sin definir|No especificado|\[[^\]]*\])/gi, '')
      .trim();

    if (!textoFinal.includes('NUEVA DERIVACIÓN')) {
      textoFinal = '=== NUEVA DERIVACIÓN ===\nSucursal elegida: ' + sucNombre + '\n' + textoFinal;
    }

    if (telCli) {
      const tieneNumero = textoFinal.includes(telCli);
      const tieneWaMe = textoFinal.includes('wa.me/' + telCli);
      if (!tieneNumero || !tieneWaMe) {
        textoFinal += `\n📞 Teléfono de contacto: +${telCli} (https://wa.me/${telCli})`;
      }
    }
    if (nomCli && !textoFinal.toLowerCase().includes('nombre de contacto:')) {
      textoFinal += `\n👤 Nombre de contacto: ${nomCli}`;
    }

    return {
      number: telSuc,
      text: textoFinal.trim()
    };
  })() }}

