function toB64Utf8(str) {
  const bytes = [];
  const encoded = encodeURIComponent(String(str ?? ''));
  for (let i = 0; i < encoded.length; i++) {
    if (encoded[i] === '%') {
      bytes.push(parseInt(encoded.slice(i + 1, i + 3), 16));
      i += 2;
    } else {
      bytes.push(encoded.charCodeAt(i));
    }
  }
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b1 = bytes[i], b2 = bytes[i + 1], b3 = bytes[i + 2];
    out += chars[b1 >> 2];
    out += chars[((b1 & 3) << 4) | ((b2 || 0) >> 4)];
    out += b2 === undefined ? '=' : chars[((b2 & 15) << 2) | ((b3 || 0) >> 6)];
    out += b3 === undefined ? '=' : chars[b3 & 63];
  }
  return out;
}
function unwrapPgDoc(r) {
  if (!r || typeof r !== 'object') return {};
  if (r.data && typeof r.data === 'object') {
    return { ...r.data, documentId: r.document_id || r.data.documentId || '' };
  }
  return r;
}

const body = $input.item.json.body || {};
const data = body.data || {};
const key = data.key || {};
const rawMsgObj = data.message || {};
const msg =
  (rawMsgObj.ephemeralMessage && rawMsgObj.ephemeralMessage.message) ||
  (rawMsgObj.viewOnceMessage && rawMsgObj.viewOnceMessage.message) ||
  (rawMsgObj.viewOnceMessageV2 && rawMsgObj.viewOnceMessageV2.message) ||
  rawMsgObj;

// Resolver @lid (WhatsApp Multi-Device Linked IDs) hacia el JID real @s.whatsapp.net
const rawRemoteJid = key.remoteJid || '';
const altRemoteJid = key.remoteJidAlt || data.remoteJidAlt || '';
const KNOWN_LID_MAP = {
  '239964151353572@lid': '5492944579792@s.whatsapp.net', // Check Oil Suc. Centro
  '9037382979830@lid': '5492944615570@s.whatsapp.net'    // Check Oil Suc. Km13
};

let remoteJid = rawRemoteJid;
if (rawRemoteJid.endsWith('@lid')) {
  if (altRemoteJid && altRemoteJid.endsWith('@s.whatsapp.net')) {
    remoteJid = altRemoteJid;
  } else if (KNOWN_LID_MAP[rawRemoteJid]) {
    remoteJid = KNOWN_LID_MAP[rawRemoteJid];
  }
}

const fromMe = Boolean(key.fromMe);
const messageId = key.id || '';
const pushName = data.pushName || 'Cliente';
const source = data.source || '';
const telefonoCliente = remoteJid.endsWith('@s.whatsapp.net')
  ? remoteJid.replace('@s.whatsapp.net', '').replace(/\D/g, '')
  : (altRemoteJid.endsWith('@s.whatsapp.net') ? altRemoteJid.replace('@s.whatsapp.net', '').replace(/\D/g, '') : '');

const SUCURSALES_MAP = {
  '5492944579792@s.whatsapp.net': { key: 'Centro', name: 'Check Oil Suc. Centro', phone: '5492944579792' },
  '239964151353572@lid': { key: 'Centro', name: 'Check Oil Suc. Centro', phone: '5492944579792' },
  '5492944638500@s.whatsapp.net': { key: 'Estadio', name: 'Check Oil Suc. Estadio', phone: '5492944638500' },
  '5492944907667@s.whatsapp.net': { key: 'Ñireco', name: 'Check Oil Suc. Ñireco', phone: '5492944907667' },
  '5492944615570@s.whatsapp.net': { key: 'Km13', name: 'Check Oil Suc. Km13', phone: '5492944615570' },
  '9037382979830@lid': { key: 'Km13', name: 'Check Oil Suc. Km13', phone: '5492944615570' },
  '5492944631155@s.whatsapp.net': { key: 'Bolsón', name: 'Check Oil Suc. Bolsón', phone: '5492944631155' },
  '5491161217529@s.whatsapp.net': { key: 'Dominico', name: 'Check Oil Suc. Dominico', phone: '5491161217529' }
};

const sucursalInfo = SUCURSALES_MAP[remoteJid] || SUCURSALES_MAP[rawRemoteJid] || null;
const esMensajeDeSucursal = Boolean(sucursalInfo && !fromMe);

const docMsg =
  msg.documentMessage ||
  (msg.documentWithCaptionMessage && msg.documentWithCaptionMessage.message && msg.documentWithCaptionMessage.message.documentMessage) ||
  null;
const imgMsg = msg.imageMessage || null;

const ctxInfo =
  data.contextInfo ||
  (msg.extendedTextMessage && msg.extendedTextMessage.contextInfo) ||
  (docMsg && docMsg.contextInfo) ||
  (imgMsg && imgMsg.contextInfo) ||
  {};

let quotedText = '';
if (ctxInfo && ctxInfo.quotedMessage) {
  const qm = ctxInfo.quotedMessage;
  quotedText =
    qm.conversation ||
    (qm.extendedTextMessage && qm.extendedTextMessage.text) ||
    (qm.documentMessage && (qm.documentMessage.caption || qm.documentMessage.fileName)) ||
    (qm.imageMessage && qm.imageMessage.caption) ||
    '';
}
const quotedStanzaId = (ctxInfo && ctxInfo.stanzaId) || '';

let texto = '';
let mediaCaption = '';
let tipoMensaje = 'texto';
let esStickerOReaccion = false;
let mediaFileName = '';
let mediaMimeType = '';
let inlineBase64 = data.base64 || msg.base64 || '';

if (typeof msg.conversation === 'string' && msg.conversation.trim()) {
  texto = msg.conversation.trim();
} else if (msg.extendedTextMessage && msg.extendedTextMessage.text) {
  texto = String(msg.extendedTextMessage.text).trim();
} else if (docMsg) {
  tipoMensaje = 'documento';
  mediaFileName = docMsg.fileName || docMsg.title || 'Presupuesto_CheckOil.pdf';
  mediaMimeType = docMsg.mimetype || 'application/pdf';
  mediaCaption = docMsg.caption ? String(docMsg.caption).trim() : '';
  texto = mediaCaption
    ? `[DOCUMENTO ADJUNTO: ${mediaFileName}] ${mediaCaption}`
    : (fromMe ? `[DOCUMENTO ENVIADO POR OPERADOR: ${mediaFileName}]` : `[DOCUMENTO ADJUNTO: ${mediaFileName}]`);
} else if (imgMsg) {
  tipoMensaje = 'imagen';
  mediaFileName = 'cotizacion_imagen.jpg';
  mediaMimeType = imgMsg.mimetype || 'image/jpeg';
  mediaCaption = imgMsg.caption ? String(imgMsg.caption).trim() : '';
  const cap = mediaCaption ? ` (${mediaCaption})` : '';
  texto = fromMe ? `[IMAGEN ENVIADA POR OPERADOR]${cap}` : `[IMAGEN ADJUNTA]${cap}`;
} else if (msg.audioMessage) {
  tipoMensaje = 'audio';
  texto = fromMe ? '[AUDIO ENVIADO POR OPERADOR]' : '[AUDIO ENVIADO POR EL CLIENTE]';
} else if (msg.stickerMessage || msg.reactionMessage) {
  esStickerOReaccion = true;
  tipoMensaje = 'sticker_reaccion';
}

const esGrupoOBroadcast =
  !remoteJid ||
  remoteJid.endsWith('@g.us') ||
  remoteJid === 'status@broadcast';

const esSucursalOGrupo = esGrupoOBroadcast || Boolean(sucursalInfo);

const limpio = texto.toLowerCase().replace(/[\!\?\.\,\s]+/g, ' ').trim();
const CORTESIAS = [
  'ok', 'okay', 'dale', 'gracias', 'muchas gracias', 'mil gracias',
  'buenisimo gracias', 'buenísimo gracias', 'listo gracias', 'genial gracias',
  'perfecto gracias', 'ok gracias', 'dale gracias', '👍', '🙏', '👌', '🙌'
];
const esCortesia = !fromMe && !esMensajeDeSucursal && CORTESIAS.includes(limpio);

$input.item.json.remoteJid = remoteJid;
$input.item.json.rawRemoteJid = rawRemoteJid;
$input.item.json.remoteJidB64 = toB64Utf8(remoteJid);
$input.item.json.telefonoCliente = telefonoCliente;
$input.item.json.mensajeCliente = texto;
$input.item.json.mediaCaption = mediaCaption;
$input.item.json.fromMe = fromMe;
$input.item.json.messageId = messageId;
$input.item.json.pushName = pushName;
$input.item.json.source = source;
$input.item.json.tipoMensaje = tipoMensaje;
$input.item.json.esStickerOReaccion = esStickerOReaccion;
$input.item.json.esGrupoOBroadcast = esGrupoOBroadcast;
$input.item.json.esSucursalOGrupo = esSucursalOGrupo;
$input.item.json.esMensajeDeSucursal = esMensajeDeSucursal;
$input.item.json.sucursalOrigenKey = sucursalInfo ? sucursalInfo.key : '';
$input.item.json.sucursalOrigenNombre = sucursalInfo ? sucursalInfo.name : '';
$input.item.json.sucursalOrigenPhone = sucursalInfo ? sucursalInfo.phone : '';
$input.item.json.quotedText = String(quotedText || '').trim();
$input.item.json.quotedStanzaId = quotedStanzaId;
$input.item.json.mediaFileName = mediaFileName;
$input.item.json.mediaMimeType = mediaMimeType;
$input.item.json.inlineBase64 = inlineBase64;
$input.item.json.rawEvolutionKey = key;
$input.item.json.rawEvolutionMessage = rawMsgObj;
$input.item.json.esCortesia = esCortesia;

return $input.item;

values.content:
=Actúas como un analista de calidad y compresor de memoria de Check-Oil.
Analiza la última interacción de WhatsApp combinándola con el Resumen anterior (NO pierdas datos previos del vehículo como Marca y Modelo si ahora el cliente solo respondió el Motor o la Sucursal) y devuelve ÚNICAMENTE un objeto JSON válido (sin bloques markdown ```json) con esta estructura exacta:
{
  "resumen_historico": "Máximo 3 líneas en viñetas con datos duros acumulados: Marca y Modelo, Motor, Año (si lo dijo), Sucursal preferida, Nombre, Teléfono y último interés",
  "resumen_charla": "Resumen ejecutivo de 1 a 2 oraciones sobre qué buscaba el cliente y en qué estado quedó la conversación",
  "estado_charla": "derivada | esperando_cotizacion | presupuesto_enviado | en_curso | incompleta | fuera_de_contexto | atendida_humano",
  "vehiculo": "Marca Modelo Año Motor combinados sin escribir la palabra 'No especificado' (solo escribe 'No especificado' si no se conoce absolutamente ningún dato del auto)",
  "sucursal_elegida": "Centro | Estadio | Ñireco | Km13 | Bolsón | Dominico | Sin definir",
  "cliente_nombre": "Nombre del cliente o Sin definir",
  "cliente_telefono": "Teléfono indicado o Sin definir",
  "fuera_de_contexto": "si | no",
  "incompleta_motivo": "Si quedó incompleta o fuera de contexto, explica brevemente qué faltó o qué preguntó que no tenía relación. Si no, deja vacío",
  "pregunta_detectada": "Si el cliente hizo una pregunta fuera de lo habitual, repuesto no trabajado o duda que requirió operador humano, escríbela aquí. Si no, deja vacío",
  "aprendizaje_sugerido": "Si hubo una pregunta fuera de contexto, charla incompleta o respuesta de un operador humano de la que el bot pueda aprender una regla para el futuro, redacta la regla sugerida aquí. Si no, deja vacío"
}

DATOS DE LA INTERACCIÓN:
- Resumen anterior: {{ $json.resumenAnterior || 'Ninguno' }}
- Teléfono de WhatsApp detectado del cliente: {{ $json.telefonoCliente }}
- Nombre detectado del cliente: {{ $json.pushName }}
- Quién escribió ahora: {{ $json.esIntervencionHumana ? 'OPERADOR HUMANO DE CHECK-OIL' : ('CLIENTE (' + ($json.pushName || $json.remoteJid) + ')') }}
- Mensaje recibido: {{ $json.mensajeCliente }}
- Respuesta del Bot / Estado: {{ $json.output }}
- Modo actual: {{ $json.modoInteraccion }}

