}

const ultimoBotEnHist = [...historialPrev].reverse().find(m => m && m.rol === 'bot');
const tieneMensajesCliente = historialPrev.some(m => m && m.rol === 'cliente') || Boolean(sesion.resumen_historico && sesion.resumen_historico !== 'Primer contacto. No hay historial previo.');

const esIdDeApi = (wh.messageId || '').startsWith('3EB0') || (wh.messageId || '').startsWith('BAE5');
const msgTrim = (wh.mensajeCliente || '').trim();
const esMismoTextoBot =
  (sesion.ultimo_msg_bot && msgTrim && sesion.ultimo_msg_bot.trim() === msgTrim) ||
  (ultimoBotEnHist && ultimoBotEnHist.texto && msgTrim && ultimoBotEnHist.texto.trim() === msgTrim);

const esEcoMensajeSucursalAlCliente =
  wh.fromMe &&
  (
    msgTrim.includes('Presupuesto adjunto — Check-Oil') ||
    msgTrim.includes('Presupuesto adjunto — Check Oil') ||
    msgTrim.startsWith('Desde Check Oil Suc.') ||
    msgTrim.startsWith('Te enviamos adjunto el presupuesto de Check Oil') ||
    msgTrim.startsWith('Te enviamos el presupuesto de Check Oil') ||
    (sesion.fecha_respuesta_cotizacion && Math.abs(Date.now() - new Date(sesion.fecha_respuesta_cotizacion).getTime()) < 90000) ||
    (sesion.ultima_interaccion && sesion.estado_cotizacion === 'esperando_respuesta_cliente' && Math.abs(Date.now() - new Date(sesion.ultima_interaccion).getTime()) < 30000)
  );

const esEcoBot = wh.fromMe && (esIdDeApi || esMismoTextoBot || esEcoMensajeSucursalAlCliente);
const esIntervencionHumana = wh.fromMe && !esEcoBot;

let botPausado = sesion.bot_pausado === true || sesion.bot_pausado === 'true';
let motivoPausa = sesion.motivo_pausa || '';
let pausadoEn = sesion.pausado_en || '';

if (botPausado && !wh.fromMe && pausadoEn) {
  const horasPausa = (Date.now() - new Date(pausadoEn).getTime()) / (1000 * 60 * 60);
  if (horasPausa > 6) {
    botPausado = false;
    motivoPausa = '';
    pausadoEn = '';
  }
}

if (esIntervencionHumana && autoPausaHumana && tieneMensajesCliente) {
  botPausado = true;
  motivoPausa = 'Operador humano intervino desde WhatsApp';
  pausadoEn = new Date().toISOString();
}

let reglasLista = [];
try {
  if (config.reglas_aprendidas_json) {
    const parsed = JSON.parse(config.reglas_aprendidas_json);
    if (Array.isArray(parsed)) {
      reglasLista = parsed
        .filter(r => r && r.activa !== false)
        .map(r => `- Cuando consulten sobre "${r.pregunta || r.tema}": ${r.respuesta}`);
    }
  }
} catch (e) {}

if (config.prompt_extra && String(config.prompt_extra).trim()) {
  reglasLista.unshift(`- DIRECTIVA GENERAL: ${String(config.prompt_extra).trim()}`);
}

const estadoCotizacionActual = sesion.estado_cotizacion || '';
const ticketIdActual = sesion.ticket_id || '';
const sucursalCotizacionActual = sesion.sucursal_cotizacion || sesion.sucursal_elegida || '';
const ultimaPreguntaSucursal = sesion.ultima_pregunta_sucursal || '';
const vehiculoAnterior = String(sesion.vehiculo || '')
  .replace(/\(Presupuesto Comercial\)/gi, '')
  .replace(/\bNo especificado\b/gi, '')
  .replace(/\bNo aplica\b/gi, '')
  .replace(/\s+/g, ' ')
  .trim();

let cotizacionActualObj = null;
try {
  if (sesion.cotizacion_actual_json) {
    cotizacionActualObj = typeof sesion.cotizacion_actual_json === 'string'
      ? JSON.parse(sesion.cotizacion_actual_json)
      : sesion.cotizacion_actual_json;
  }
} catch (e) {}

// Detección inteligente de calles (ej. Gallardo -> Centro o Estadio)
const msgLow = msgTrim.toLowerCase();
let pistaCalleUbicacion = '';
if (msgLow.includes('gallardo')) {
  if (msgLow.includes('735') || msgLow.includes('centro')) {
    pistaCalleUbicacion = '\n📍 CALLE DETECTADA: El cliente indicó Gallardo 735 / Centro -> corresponde a Check Oil Suc. Centro (Bariloche).\n';
  } else if (msgLow.includes('1414') || msgLow.includes('estadio')) {
    pistaCalleUbicacion = '\n📍 CALLE DETECTADA: El cliente indicó Gallardo 1414 / Estadio -> corresponde a Check Oil Suc. Estadio (Bariloche).\n';
  } else {
    pistaCalleUbicacion =
      '\n📍 ATENCIÓN — DESAMBIGUACIÓN OBLIGATORIA POR CALLE "GALLARDO":\n' +
      'El cliente acaba de mencionar "Gallardo". En Bariloche sobre Av. Ángel Gallardo Check-Oil tiene SOLAMENTE dos sucursales: **Sucursal Centro (Av. Ángel Gallardo 735)** y **Sucursal Estadio (Av. Ángel Gallardo 1414)**.\n' +
      'PROHIBIDO ofrecer El Bolsón, Buenos Aires, Ñireco o Km13. Responde indicando únicamente esas dos opciones de calle Gallardo: "¿En cuál de nuestras dos sucursales de calle Gallardo preferís ser atendido: **Centro (Av. Gallardo 735)** o **Estadio (Av. Gallardo 1414)**?" (agregando Marca y Modelo o Motor únicamente si todavía faltan).\n';
  }
} else if (msgLow.includes('los ñires') || msgLow.includes('los nires')) {
  pistaCalleUbicacion = '\n📍 CALLE DETECTADA: "Los Ñires" corresponde a Check Oil Suc. Ñireco (Bariloche).\n';
} else if (msgLow.includes('bustillo')) {
  pistaCalleUbicacion = '\n📍 CALLE DETECTADA: "Bustillo" corresponde a Check Oil Suc. Km13 (Bariloche).\n';
