        `Si querés confirmarlo para coordinar con la sucursal, avisanos por este medio. Si necesitás algo más, estamos a tu disposición.`;
    }
  } else {
    // Presupuesto enviado en texto por la sucursal -> reenviar literalmente el texto de la sucursal
    textoParaCliente =
      `Te enviamos el presupuesto de ${wh.sucursalOrigenNombre}:\n\n` +
      `${textoSucursalLimpio}\n\n` +
      `Si querés confirmarlo para coordinar con la sucursal, avisanos por este medio. Si necesitás algo más, estamos a tu disposición.`;
  }

  historial.push({
    rol: 'sucursal',
    nombre: wh.sucursalOrigenNombre,
    texto: `[PRESUPUESTO RECIBIDO #${registroCotizacion.ticket_id} • Demora hábil: ${demoraNetaSucursalMin} min • Formato: ${formatoOrigen.toUpperCase()}] ${registroCotizacion.resumen_items || prep.mediaName || textoSucursalLimpio} ${registroCotizacion.total_cotizado ? '($' + registroCotizacion.total_cotizado.toLocaleString('es-AR') + ')' : ''}`.trim(),
    fecha: ahora
  });
  historial.push({
    rol: 'bot',
    texto: textoParaCliente + (enviarPdfAlCliente ? `\n📎 [Archivo reenviado: ${prep.mediaName}]` : ''),
    fecha: ahora
  });
}

if (historial.length > 45) {
  historial = historial.slice(historial.length - 45);
}

const vehSessionClean = String(targetSession.vehiculo || 'No especificado')
  .replace(/\(Presupuesto Comercial\)/gi, '')
  .trim() || 'No especificado';

const __outObj = {
  guardarSesion: true,
  enviarPdfAlCliente,
  enviarTextoAlCliente: Boolean(textoParaCliente),
  enviarAclaracionASucursal: false,
  clienteJid: targetSession.documentId,
  sucursalOrigenNombre: wh.sucursalOrigenNombre,
  textoParaCliente,
  mediaBase64: prep.hasRealMedia ? (prep.mediaBase64 || '') : '',
  mediaMime: prep.hasRealMedia ? (prep.mediaMime || 'application/pdf') : 'application/pdf',
  mediaTypeEvolution: wh.tipoMensaje === 'imagen' ? 'image' : 'document',
  mediaName: prep.hasRealMedia ? (prep.mediaName || 'Presupuesto_CheckOil.pdf') : '',
  documentId: targetSession.documentId,
  resumen_historico: targetSession.resumen_historico || '',
  resumen_charla: tipoRespuesta === 'presupuesto'
    ? `Presupuesto #${targetSession.ticket_id} enviado al cliente (${demoraNetaSucursalMin} min hábiles). Esperando confirmación.`
    : `Sucursal consultó al cliente (#${targetSession.ticket_id}): ${ultimaPreguntaSucursal}`,
  estado_charla: estadoCharlaNuevo,
  bot_pausado: String(targetSession.bot_pausado || 'false'),
  motivo_pausa: targetSession.motivo_pausa || '',
  pausado_en: targetSession.pausado_en || '',
  vehiculo: vehSessionClean,
  sucursal_elegida: targetSession.sucursal_elegida || wh.sucursalOrigenKey,
  cliente_nombre: targetSession.cliente_nombre || 'Cliente',
  cliente_telefono: targetSession.cliente_telefono || targetSession.documentId.replace('@s.whatsapp.net', ''),
  fuera_de_contexto: targetSession.fuera_de_contexto || 'no',
  incompleta_motivo: targetSession.incompleta_motivo || '',
  pregunta_detectada: targetSession.pregunta_detectada || '',
  aprendizaje_sugerido: targetSession.aprendizaje_sugerido || '',
  estado_aprendizaje: targetSession.estado_aprendizaje || '',
  historial_json: JSON.stringify(historial),
  total_mensajes: String(historial.length),
  ultima_interaccion: ahora,
  ultimo_msg_bot: textoParaCliente,
  ticket_id: targetSession.ticket_id || '',
  estado_cotizacion: estadoCotizacionNuevo,
  sucursal_cotizacion: wh.sucursalOrigenKey,
  fecha_pedido_cotizacion: inicioTotalIso,
  ultimo_pedido_sucursal_en: targetSession.ultimo_pedido_sucursal_en || inicioTotalIso,
  fecha_respuesta_cotizacion: fechaRespuestaCotizacion,
  fecha_confirmacion: targetSession.fecha_confirmacion || '',
  demora_total_min: String(demoraCorridaMin),
  demora_habil_min: String(demoraHabilTotalMin),
  demora_neta_sucursal_min: String(demoraNetaSucursalMin),
  segundos_acumulados_sucursal: String(segAcumTotal),
  recordatorio_enviado: String(targetSession.recordatorio_enviado || 'false'),
  ultima_pregunta_sucursal: tipoRespuesta === 'presupuesto' ? '' : ultimaPreguntaSucursal,
  cotizacion_actual_json: cotizacionActualJson,
  cotizaciones_historial_json: cotizacionesHistorialJson
};

const __dbFields = {
  documentId: __outObj.documentId,
  resumen_historico: __outObj.resumen_historico,
  resumen_charla: __outObj.resumen_charla,
  estado_charla: __outObj.estado_charla,
  bot_pausado: __outObj.bot_pausado,
  motivo_pausa: __outObj.motivo_pausa,
  pausado_en: __outObj.pausado_en,
  vehiculo: __outObj.vehiculo,
  sucursal_elegida: __outObj.sucursal_elegida,
  cliente_nombre: __outObj.cliente_nombre,
  cliente_telefono: __outObj.cliente_telefono,
  fuera_de_contexto: __outObj.fuera_de_contexto,
  incompleta_motivo: __outObj.incompleta_motivo,
  pregunta_detectada: __outObj.pregunta_detectada,
  aprendizaje_sugerido: __outObj.aprendizaje_sugerido,
  estado_aprendizaje: __outObj.estado_aprendizaje,
  historial_json: __outObj.historial_json,
  total_mensajes: __outObj.total_mensajes,
  ultima_interaccion: __outObj.ultima_interaccion,
  ultimo_msg_bot: __outObj.ultimo_msg_bot,
  ticket_id: __outObj.ticket_id,
  estado_cotizacion: __outObj.estado_cotizacion,
  sucursal_cotizacion: __outObj.sucursal_cotizacion,
  fecha_pedido_cotizacion: __outObj.fecha_pedido_cotizacion,
  ultimo_pedido_sucursal_en: __outObj.ultimo_pedido_sucursal_en,
  fecha_respuesta_cotizacion: __outObj.fecha_respuesta_cotizacion,
  fecha_confirmacion: __outObj.fecha_confirmacion,
  demora_total_min: __outObj.demora_total_min,
  demora_habil_min: __outObj.demora_habil_min,
  demora_neta_sucursal_min: __outObj.demora_neta_sucursal_min,
  segundos_acumulados_sucursal: __outObj.segundos_acumulados_sucursal,
  recordatorio_enviado: __outObj.recordatorio_enviado,
  ultima_pregunta_sucursal: __outObj.ultima_pregunta_sucursal,
  cotizacion_actual_json: __outObj.cotizacion_actual_json,
  cotizaciones_historial_json: __outObj.cotizaciones_historial_json
};

__outObj.docIdB64 = toB64Utf8(__outObj.documentId);
__outObj.payloadB64 = toB64Utf8(JSON.stringify(__dbFields));
return [{ json: __outObj }];

