function toB64Utf8(str) {
  const bytes = [];
  const encoded = encodeURIComponent(String(str ?? ''));
  for (let i = 0; i < encoded.length; i++) {
    if (encoded[i] === '%') {
      bytes.push(parseInt(encoded.slice(i + 1, i + 3), 16));
      i += 2;
    } else {
      bytes.push(encoded.charCodeAt(i));
    }
  }
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b1 = bytes[i], b2 = bytes[i + 1], b3 = bytes[i + 2];
    out += chars[b1 >> 2];
    out += chars[((b1 & 3) << 4) | ((b2 || 0) >> 4)];
    out += b2 === undefined ? '=' : chars[((b2 & 15) << 2) | ((b3 || 0) >> 6)];
    out += b3 === undefined ? '=' : chars[b3 & 63];
  }
  return out;
}
function unwrapPgDoc(r) {
  if (!r || typeof r !== 'object') return {};
  if (r.data && typeof r.data === 'object') {
    return { ...r.data, documentId: r.document_id || r.data.documentId || '' };
  }
  return r;
}

const allDocs = $input.all().map(i => unwrapPgDoc(i.json)).filter(d => d && d.documentId);
const config = allDocs.find(d => d.documentId === 'bot_config_global') || {};

const botActivo = config.bot_activo !== false && config.bot_activo !== 'false';
const modoConfig = String(config.modo_presupuesto_intermediario || 'activo').toLowerCase();
const fechaInicio = String(config.fecha_inicio_intermediario || '2026-11-09').slice(0, 10).trim();
const hoyArgentina = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Argentina/Buenos_Aires',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

const intermediarioActivo =
  modoConfig === 'true' ||
  modoConfig === 'activo' ||
  (modoConfig === 'programado' && Boolean(fechaInicio && hoyArgentina >= fechaInicio));

if (!botActivo || !intermediarioActivo) {
  return [];
}

let schedule = {
  lun_vie_apertura: '08:30',
  lun_vie_cierre: '20:00',
  sab_apertura: '09:00',
  sab_cierre: '13:30',
  dom_abierto: false
};
try {
  if (config.horario_comercial_json) {
    const p = typeof config.horario_comercial_json === 'string'
      ? JSON.parse(config.horario_comercial_json)
      : config.horario_comercial_json;
    schedule = { ...schedule, ...p };
  }
} catch (e) {}

const toMin = (hhmm) => {
  const [h, m] = String(hhmm || '08:30').split(':').map(Number);
  return (h || 0) * 60 + (m || 0);
};
const lvOpen = toMin(schedule.lun_vie_apertura);
const lvClose = toMin(schedule.lun_vie_cierre);
const sabOpen = toMin(schedule.sab_apertura);
const sabClose = toMin(schedule.sab_cierre);

const fmt = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Argentina/Buenos_Aires',
  weekday: 'short',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false
});

function estaEnHorarioComercial(dateObj) {
  const parts = fmt.formatToParts(dateObj);
  const wk = (parts.find(p => p.type === 'weekday') || {}).value || '';
  const hh = Number((parts.find(p => p.type === 'hour') || {}).value || 0) % 24;
  const mm = Number((parts.find(p => p.type === 'minute') || {}).value || 0);
  const curMin = hh * 60 + mm;
  if (wk === 'Sun') return Boolean(schedule.dom_abierto && curMin >= sabOpen && curMin < sabClose);
  if (wk === 'Sat') return curMin >= sabOpen && curMin < sabClose;
  return curMin >= lvOpen && curMin < lvClose;
}

function calcularMinutosHabiles(startIso, endDate) {
  const start = new Date(startIso);
  if (isNaN(start.getTime()) || endDate <= start) return 0;
  let count = 0;
  let cursor = Math.floor(start.getTime() / 60000) * 60000;
  const endMs = Math.floor(endDate.getTime() / 60000) * 60000;
  const maxStepEnd = Math.min(endMs, cursor + 4320 * 60000);
  while (cursor < maxStepEnd) {
    if (estaEnHorarioComercial(new Date(cursor))) count++;
    cursor += 60000;
  }
  return count;
}

const ahora = new Date();
if (!estaEnHorarioComercial(ahora)) {
  return [];
}

const intervaloMin = Math.max(5, Number(config.sla_recordatorio_minutos || 15));
const maxRecordatorios = Math.max(1, Number(config.max_recordatorios_sla || 3));

const SUCURSAL_PHONES = {
  centro: '5492944579792',
  estadio: '5492944638500',
  'ñireco': '5492944907667',
  nireco: '5492944907667',
  km13: '5492944615570',
  'bolsón': '5492944631155',
  bolson: '5492944631155',
  dominico: '5491161217529'
};

const vencidos = [];
for (const doc of allDocs) {
  const docId = doc.documentId;
  if (!docId || docId === 'bot_config_global' || docId === '__bot_config__') continue;
  if (doc.estado_cotizacion !== 'esperando_sucursal') continue;

  const cantPrev = Number(doc.cantidad_recordatorios_sla || (doc.recordatorio_enviado === 'true' && !doc.ultimo_recordatorio_en ? 1 : 0));
  if (cantPrev >= maxRecordatorios) continue;

  const pedidoInicialIso = doc.ultimo_pedido_sucursal_en || doc.fecha_pedido_cotizacion;
  if (!pedidoInicialIso) continue;

  const referenciaIso = doc.ultimo_recordatorio_en || pedidoInicialIso;
  const minRealesDesdeRef = Math.floor((ahora.getTime() - new Date(referenciaIso).getTime()) / 60000);
  const minHabilesDesdeRef = calcularMinutosHabiles(referenciaIso, ahora);
  const minHabilesTotales = calcularMinutosHabiles(pedidoInicialIso, ahora);

  if (minHabilesDesdeRef >= intervaloMin && minRealesDesdeRef >= intervaloMin) {
    const sucKey = String(doc.sucursal_cotizacion || doc.sucursal_elegida || 'Centro').toLowerCase();
    let phone = '5492944579792';
    for (const [k, p] of Object.entries(SUCURSAL_PHONES)) {
      if (sucKey.includes(k)) {
        phone = p;
        break;
      }
    }
    const nuevoConteo = cantPrev + 1;
    const slaPatch = {
      documentId: docId,
      recordatorio_enviado: 'true',
      ultimo_recordatorio_en: ahora.toISOString(),
      cantidad_recordatorios_sla: String(nuevoConteo)
    };
    vencidos.push({
      json: {
        ...doc,
        ...slaPatch,
        docIdB64: toB64Utf8(docId),
        payloadB64: toB64Utf8(JSON.stringify(slaPatch)),
        sucursalReminderPhone: phone,
        minutosHabilesEspera: minHabilesTotales,
        textoRecordatorio:
          `⏰ RECORDATORIO DE PRESUPUESTO #${doc.ticket_id || 'PENDIENTE'} (${nuevoConteo}/${maxRecordatorios})\n` +
          `Hace ${minHabilesTotales} min hábiles un cliente espera cotización de ${doc.sucursal_elegida || 'Sucursal Centro'}:\n` +
          `🚗 Vehículo: ${doc.vehiculo || 'Ver mensaje anterior'}\n` +
          `👉 Por favor respondé citando el pedido con el PDF o texto del presupuesto (o escribime si necesitás algún dato adicional del vehículo).`
      }
    });
  }
}

return vencidos;
